import 'package:flutter/material.dart';
import '../api.dart';
import 'login_screen.dart';
class RegisterScreen extends StatefulWidget { const RegisterScreen({super.key}); @override State<RegisterScreen> createState() => _RegisterScreenState(); }
class _RegisterScreenState extends State<RegisterScreen> { final name = TextEditingController(); final email = TextEditingController(); final city = TextEditingController(); final password = TextEditingController(); bool loading = false; String? error; @override void dispose() { name.dispose(); email.dispose(); city.dispose(); password.dispose(); super.dispose(); } Future<void> submit() async { if (password.text.length < 12) { setState(() => error = 'La contraseña debe tener al menos 12 caracteres.'); return; } setState(() { loading = true; error = null; }); try { await JopetsApi().register(name: name.text.trim(), email: email.text.trim(), city: city.text.trim(), password: password.text); if (mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const LoginScreen())); } catch (e) { if (mounted) setState(() => error = e.toString()); } finally { if (mounted) setState(() => loading = false); } }
@override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Crear cuenta')), body: ListView(padding: const EdgeInsets.all(20), children: [TextField(controller: name, decoration: const InputDecoration(labelText: 'Nombre')), TextField(controller: email, decoration: const InputDecoration(labelText: 'Correo')), TextField(controller: city, decoration: const InputDecoration(labelText: 'Ciudad')), TextField(controller: password, obscureText: true, decoration: const InputDecoration(labelText: 'Contraseña')), if (error != null) Text(error!, style: const TextStyle(color: Colors.red)), FilledButton(onPressed: loading ? null : submit, child: Text(loading ? 'Enviando…' : 'Registrarme'))])); }
